//! The feed on disk — the one impure edge of this crate.
//!
//! Everything in [`crate`] proper is pure; this module is where it touches a filesystem, and it is
//! deliberately small. It owns three questions and nothing else: where the feed lives, how an entry
//! is appended, and which of the four [`FeedState`]s a directory is currently in.
//!
//! ## The layout, and why it is a directory rather than a database
//!
//! ```text
//! <base>/imagination/
//!   entries.jsonl     append-only, one Entry per line, oldest first
//!   fault.txt         present only while the producer is broken; its content is the reason
//!   <id>.png          one image per entry, named by the entry id
//! ```
//!
//! Append-only JSONL beside its images, for the same reason `bsc ear` stores transcripts that way:
//! the entries are small and the IMAGES are the only large thing, so the bound that matters is
//! already enforced on files. A database to manage a few hundred lines would be more machinery than
//! the problem deserves, and a line per record stays readable by `grep` when something is wrong.
//!
//! ## Absent is a state, not an error
//!
//! A missing directory means **no producer has ever run** — nobody is imagining. That is reported
//! as [`FeedState::Absent`] rather than as an empty feed or an I/O failure, because a surface that
//! says "nothing" while the thing behind it is not running is this codebase's most-repeated bug. An
//! unreadable directory that DOES exist is a different answer again ([`FeedState::Failing`]): it
//! exists, so something made it, and it is now broken.

use crate::{retain, Budget, Entry, FeedState};
use std::path::{Path, PathBuf};

/// The feed directory under a base dir (`~/.base-studio-code`).
pub fn feed_dir(base: &Path) -> PathBuf {
    base.join("imagination")
}

/// The append-only entry log within a feed directory.
pub fn entries_path(dir: &Path) -> PathBuf {
    dir.join("entries.jsonl")
}

/// The fault marker. Present only while the producer cannot draw.
pub fn fault_path(dir: &Path) -> PathBuf {
    dir.join("fault.txt")
}

/// The image file for an entry id.
pub fn image_path(dir: &Path, id: &str) -> PathBuf {
    dir.join(format!("{id}.png"))
}

/// Parse an entry log, skipping lines that do not parse.
///
/// A corrupt line is SKIPPED rather than failing the read: the log is append-only and written by a
/// live producer, so a torn final line is an ordinary race, not a broken feed. Returning `Failing`
/// for it would blank the widget every time a write landed mid-read.
pub fn parse_entries(text: &str) -> Vec<Entry> {
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .filter_map(|l| serde_json::from_str::<Entry>(l).ok())
        .collect()
}

/// Which state the feed at `dir` is in, with the budget already applied.
pub fn read(dir: &Path, now_unix_ms: i64, budget: &Budget) -> FeedState {
    if !dir.exists() {
        return FeedState::Absent;
    }
    if let Ok(reason) = std::fs::read_to_string(fault_path(dir)) {
        let reason = reason.trim().to_string();
        return FeedState::Failing {
            reason: if reason.is_empty() { "the producer reported a fault with no message".into() } else { reason },
        };
    }
    let text = match std::fs::read_to_string(entries_path(dir)) {
        Ok(t) => t,
        // The directory exists but the log does not: a producer has started and drawn nothing yet.
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return FeedState::Empty,
        Err(e) => return FeedState::Failing { reason: format!("cannot read the entry log: {e}") },
    };
    let entries = retain(&parse_entries(&text), now_unix_ms, budget);
    if entries.is_empty() {
        FeedState::Empty
    } else {
        FeedState::Ready { entries }
    }
}

/// Append one entry to the log, creating the directory if needed.
pub fn append(dir: &Path, entry: &Entry) -> Result<(), String> {
    use std::io::Write;
    std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    let line = serde_json::to_string(entry).map_err(|e| format!("cannot serialise the entry: {e}"))?;
    let mut f = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(entries_path(dir))
        .map_err(|e| format!("cannot open the entry log: {e}"))?;
    writeln!(f, "{line}").map_err(|e| format!("cannot append to the entry log: {e}"))
}

/// Record that the producer cannot draw, so the surface can say so.
pub fn set_fault(dir: &Path, reason: &str) -> Result<(), String> {
    std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    std::fs::write(fault_path(dir), reason).map_err(|e| format!("cannot write the fault: {e}"))
}

/// Clear the fault marker. Absent is success — clearing what is not there is not an error.
pub fn clear_fault(dir: &Path) -> Result<(), String> {
    match std::fs::remove_file(fault_path(dir)) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(format!("cannot clear the fault: {e}")),
    }
}

/// Enforce the bound: rewrite the log to what [`retain`] keeps, and delete the images of everything
/// it dropped. Returns how many entries were evicted.
///
/// The IMAGES are the reason this exists. Entries are bytes; images are megabytes, and a bound that
/// trimmed the log while leaving the pictures on disk would enforce nothing that matters — and
/// would leave pictures of what was said in the room lying around past the window that promised to
/// remove them.
pub fn sweep(dir: &Path, now_unix_ms: i64, budget: &Budget) -> Result<usize, String> {
    let text = match std::fs::read_to_string(entries_path(dir)) {
        Ok(t) => t,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(e) => return Err(format!("cannot read the entry log: {e}")),
    };
    let all = parse_entries(&text);
    let kept = retain(&all, now_unix_ms, budget);
    let gone = crate::evicted(&all, now_unix_ms, budget);
    if gone.is_empty() {
        return Ok(0);
    }
    for e in &gone {
        // A missing image is not a failure — the sweep is idempotent on purpose, so a producer that
        // died between writing the log line and the file cannot wedge it.
        let _ = std::fs::remove_file(image_path(dir, &e.id));
    }
    // Oldest first on disk, matching how the log is appended.
    let mut ordered = kept;
    ordered.sort_by_key(|e| e.at_unix_ms);
    let body: String = ordered
        .iter()
        .filter_map(|e| serde_json::to_string(e).ok())
        .map(|l| format!("{l}\n"))
        .collect();
    std::fs::write(entries_path(dir), body).map_err(|e| format!("cannot rewrite the entry log: {e}"))?;
    Ok(gone.len())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Tier;

    /// A unique scratch dir per test. Removed on drop, so a failing test still cleans up.
    struct Tmp(PathBuf);
    impl Tmp {
        fn new(tag: &str) -> Tmp {
            let n = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0);
            let p = std::env::temp_dir().join(format!("bsc-imagine-{tag}-{n}"));
            std::fs::create_dir_all(&p).unwrap();
            Tmp(p)
        }
    }
    impl Drop for Tmp {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    fn entry(id: &str, at: i64) -> Entry {
        Entry {
            id: id.into(),
            at_unix_ms: at,
            transcript: "it is raining".into(),
            scene: Some("a wet street at night".into()),
            image: format!("{id}.png"),
            tier: Tier::Reflex,
            render_ms: 205,
        }
    }

    #[test]
    fn a_directory_that_does_not_exist_is_absent_not_empty() {
        // The distinction the whole FeedState enum exists for: nobody is imagining must never
        // render as the room being quiet.
        let t = Tmp::new("absent");
        let missing = t.0.join("never-created");
        assert_eq!(read(&missing, 0, &Budget::default()), FeedState::Absent);
    }

    #[test]
    fn a_directory_with_no_log_yet_is_empty() {
        let t = Tmp::new("empty");
        assert_eq!(read(&t.0, 0, &Budget::default()), FeedState::Empty);
    }

    #[test]
    fn a_fault_is_reported_with_its_reason_and_outranks_entries() {
        let t = Tmp::new("fault");
        append(&t.0, &entry("a", 100)).unwrap();
        set_fault(&t.0, "no image generator on PATH").unwrap();
        let got = read(&t.0, 100, &Budget::default());
        let FeedState::Failing { reason } = &got else { panic!("expected Failing, got {got:?}") };
        assert_eq!(reason, "no image generator on PATH");
        // Clearing restores the entries rather than leaving the feed stuck.
        clear_fault(&t.0).unwrap();
        assert!(matches!(read(&t.0, 100, &Budget::default()), FeedState::Ready { .. }));
        // Clearing twice is not an error.
        clear_fault(&t.0).unwrap();
    }

    #[test]
    fn an_empty_fault_message_still_says_something() {
        // A message-less fault must not read as "no reason given" ambiguity in the UI.
        let t = Tmp::new("faultblank");
        set_fault(&t.0, "   ").unwrap();
        let got = read(&t.0, 0, &Budget::default());
        let FeedState::Failing { reason } = &got else { panic!("expected Failing, got {got:?}") };
        assert!(!reason.is_empty(), "a fault must carry SOME reason");
    }

    #[test]
    fn entries_round_trip_and_come_back_newest_first() {
        let t = Tmp::new("rt");
        append(&t.0, &entry("old", 100)).unwrap();
        append(&t.0, &entry("new", 300)).unwrap();
        let got = read(&t.0, 300, &Budget::default());
        let FeedState::Ready { entries } = &got else { panic!("expected Ready, got {got:?}") };
        assert_eq!(entries.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), ["new", "old"]);
        assert_eq!(entries[0].scene.as_deref(), Some("a wet street at night"));
    }

    #[test]
    fn a_torn_final_line_is_skipped_rather_than_failing_the_whole_read() {
        // The log is appended to by a live producer, so reading mid-write is an ordinary race.
        // Failing here would blank the widget every time a write landed during a poll.
        let t = Tmp::new("torn");
        append(&t.0, &entry("good", 100)).unwrap();
        let mut raw = std::fs::read_to_string(entries_path(&t.0)).unwrap();
        raw.push_str("{\"id\":\"half-writ");
        std::fs::write(entries_path(&t.0), raw).unwrap();
        let got = read(&t.0, 100, &Budget::default());
        let FeedState::Ready { entries } = &got else { panic!("expected Ready, got {got:?}") };
        assert_eq!(entries.len(), 1);
    }

    #[test]
    fn the_sweep_deletes_the_images_of_evicted_entries_and_keeps_the_rest() {
        // The images are the whole reason the bound matters — trimming the log while leaving
        // pictures of what was said in the room on disk would enforce nothing.
        let t = Tmp::new("sweep");
        let budget = Budget { max_entries: 2, max_age_ms: 10_000 };
        for (id, at) in [("a", 100), ("b", 200), ("c", 300)] {
            append(&t.0, &entry(id, at)).unwrap();
            std::fs::write(image_path(&t.0, id), b"png").unwrap();
        }
        let evicted = sweep(&t.0, 300, &budget).unwrap();
        assert_eq!(evicted, 1, "exactly the oldest should go");
        assert!(!image_path(&t.0, "a").exists(), "the evicted image must be deleted");
        assert!(image_path(&t.0, "b").exists() && image_path(&t.0, "c").exists());
        let got = read(&t.0, 300, &budget);
        let FeedState::Ready { entries } = &got else { panic!("expected Ready, got {got:?}") };
        assert_eq!(entries.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), ["c", "b"]);
        // Idempotent: a second sweep evicts nothing and does not fail on the already-gone image.
        assert_eq!(sweep(&t.0, 300, &budget).unwrap(), 0);
    }

    #[test]
    fn sweeping_a_feed_with_no_log_is_not_an_error() {
        let t = Tmp::new("sweepnone");
        assert_eq!(sweep(&t.0, 0, &Budget::default()).unwrap(), 0);
    }
}
